    private dynamicText(row: UnionDynamic): string { const club = row.clubName ? `俱乐部<color=#fa59bc>${row.clubName}[${row.clubSign ?? ''}]</color>` : ''; const player = row.name ? `成员<color=#67b619>${row.name}[${row.pid ?? ''}]</color>` : ''; const exec = row.execName ? `成员<color=#67b619>${row.execName}[${row.execPid ?? ''}]</color>` : ''; const value = `<color=#e6910b>${row.value ?? ''}</color>`; const action = (text: string) => `<color=#e94817>${text}</color>`; const current = row.curValue === undefined ? '' : `，当前俱乐部积分为${row.curValue}`; const previous = row.preValue === undefined ? '' : `，修改前为${row.preValue}`; switch (Number(row.execType ?? 0)) { case 1: return `${club}${player}被${exec}${action('增加')}了俱乐部积分${value}${current}`; case 2: return `${club}${player}被${exec}${action('减少')}了俱乐部积分${value}${current}`; case 3: return `${club}${player}被${exec}${action('修改')}了活跃度计算为${value}${previous}`; case 4: return `${club}${player}被${exec}${action('审核加入')}了联盟`; case 5: return `${club}${player}被${exec}${action('审核退出')}了联盟`; case 6: return `${club}${player}被${exec}${action('踢出')}了联盟`; case 7: return `${club}${player}被${exec}${action('邀请加入')}了联盟`; case 8: return `${player}${action('创建')}了联盟，联盟总分为${value}`; case 9: return `${player}${action('解散')}了联盟`; case 10: return `${player}${action('启用')}了联盟`; case 11: return `${player}${action('停用')}了联盟`; case 14: return `${player}被${exec}${action('设为')}联盟管理`; case 15: return `${player}被${exec}${action('取消')}联盟管理`; case 16: return `${player}${action('创建')}了联盟房间`; case 17: return `${player}${action('修改')}了联盟房间${value}`; case 18: return `${player}${action('解散')}了联盟房间`; case 19: return `${player}${action('开启')}了加入审核`; case 20: return `${player}${action('关闭')}了加入审核`; case 21: return `${player}${action('开启')}了退出审核`; case 22: return `${player}${action('关闭')}了退出审核`; case 27: return `${player}${action('修改')}联盟名称为${value}`; case 30: return `${club}${player}${action('加入')}了联盟`; case 31: return `${club}${player}${action('退出')}了联盟`; case 32: return `${player}${action('修改')}联盟总分为${value}${previous}`; case 35: return `${player}${action('修改')}淘汰值为${value}${previous}`; case 36: case 44: return `${player}被${exec}${action('禁止游戏')}`; case 37: case 45: return `${player}被${exec}${action('取消禁止游戏')}`; case 49: return `${club}${player}被${exec}${action('修改')}为区间分成`; case 116: return `${player}被${exec}${action('同意')}复赛申请，申请时俱乐部积分为${value}`; case 117: return `${player}被${exec}${action('同意')}退赛申请，申请时俱乐部积分为${value}`; case 118: return `${player}被${exec}${action('拒绝')}退赛申请`; case 122: case 124: return `${club}${player}被${exec}${action(Number(row.execType) === 122 ? '授权增加' : '异常补偿')}俱乐部积分${value}${current}`; case 123: case 125: return `${club}${player}被${exec}${action(Number(row.execType) === 123 ? '授权减少' : '异常处罚')}俱乐部积分${value}${current}`; case 1007: return `${action('修改开局桌子最多显示')} ${value}张`; case 1017: return `${exec}${action('修改')}了${player}的生存分为${row.curValue ?? ''}${previous}`; default: return row.msg || `未知消息类型:${row.execType ?? 0}`; } }
    private dateTime(value: unknown): string { const raw = Number(value ?? 0); if (!raw) return ''; const date = new Date(raw < 100000000000 ? raw * 1000 : raw); const pad = (number: number) => String(number).padStart(2, '0'); return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`; }
