    /** 2.22 behavior: one room row expands to 396px; opening it collapses every sibling. */
    private toggleRoomControl(content: Node, selected: Node, id: number, status: number): void {
        const opening = this.expandedRoomId !== id;
        this.expandedRoomId = opening ? id : 0;
        for (const row of content.children) this.setRoomRowExpanded(row, opening && row === selected);
        const control = this.desc(selected, 'controlNode');
        if (control && opening) {
            this.active(control, 'btn_delRoom', true);
            this.active(control, 'btn_unUseing', status === 0);
            this.active(control, 'btn_useing', status !== 0);
        }
        content.getComponent(Layout)?.updateLayout();
    }
    private setRoomRowExpanded(row: Node, expanded: boolean): void {
        const control = this.desc(row, 'controlNode');
        if (!control) return;
        control.active = expanded;
        const transform = row.getComponent(UITransform);
        if (transform) transform.setContentSize(transform.contentSize.width, expanded ? 396 : 86);
    }
